sp_widget.client_script:
api.controller = function() {

    var c = this;


    /* =========================================
       FORM
       ========================================= */

    c.form = {

        ticket: "",

        rating: 0,

        comments: ""

    };


    c.submitting = false;


    /* =========================================
       SELECT RATING
       ========================================= */

    c.setRating = function(rating) {

        c.form.rating = rating;

    };


    /* =========================================
       RATING TEXT
       ========================================= */

    c.ratingText = function() {

        switch (c.form.rating) {

            case 1:
                return "Very Poor";

            case 2:
                return "Poor";

            case 3:
                return "Average";

            case 4:
                return "Good";

            case 5:
                return "Excellent";

            default:
                return "";

        }

    };


    /* =========================================
       SUBMIT FEEDBACK
       ========================================= */

    c.submitFeedback = function() {

        if (c.submitting) {

            return;

        }


        /* -------------------------------------
           VALIDATION
           ------------------------------------- */

        if (!c.form.ticket) {

            c.data.error =
                "Please select a resolved request.";

            return;

        }


        if (!c.form.rating ||
            c.form.rating < 1) {

            c.data.error =
                "Please select a rating.";

            return;

        }


        if (!c.form.comments ||
            !c.form.comments.trim()) {

            c.data.error =
                "Please enter your comments.";

            return;

        }


        c.data.error = "";

        c.submitting = true;


        /* -------------------------------------
           SEND TO SERVER
           ------------------------------------- */

        c.server.get({

            action:
                "submit_feedback",

            ticket:
                c.form.ticket,

            rating:
                c.form.rating,

            comments:
                c.form.comments

        }).then(function(response) {

            c.data.success =
                response.data.success;

            c.data.error =
                response.data.error;


            c.submitting = false;


            if (response.data.success) {

                c.form = {

                    ticket: "",

                    rating: 0,

                    comments: ""

                };

            }

        }, function() {

            c.submitting = false;

            c.data.error =
                "Something went wrong while submitting feedback.";

        });

    };


    /* =========================================
       RESET
       ========================================= */

    c.resetFeedback = function() {

        c.data.success = false;

        c.data.error = "";

        c.form = {

            ticket: "",

            rating: 0,

            comments: ""

        };

    };


    /* =========================================
       BACK TO DASHBOARD
       ========================================= */

    c.backToDashboard = function() {

        window.location.href =
            "?id=cfms_student";

    };


    /* =========================================
       MY REQUESTS
       ========================================= */

    c.myRequests = function() {

        window.location.href =
            "?id=cfms_requests";

    };

};

sp_widget.css:
/* =========================================
   CFMS STUDENT FEEDBACK
   ========================================= */

.cfms-feedback-page {
    min-height: 100vh;

    background: #f0fbfc;

    color: #263238;

    font-family:
        "Segoe UI",
        Tahoma,
        Geneva,
        Verdana,
        sans-serif;

    padding-bottom: 50px;
}


/* =========================================
   HEADER
   ========================================= */

.feedback-header {
    min-height: 105px;

    background: #00acc1;

    color: white;

    padding: 25px 7%;

    box-sizing: border-box;

    display: flex;

    align-items: center;
}


.header-left {
    display: flex;

    align-items: center;

    gap: 18px;
}


.back-btn {
    width: 42px;
    height: 42px;

    border: 1px solid rgba(255,255,255,0.7);

    border-radius: 8px;

    background: transparent;

    color: white;

    cursor: pointer;

    font-size: 16px;
}


.back-btn:hover {
    background: white;

    color: #00acc1;
}


.header-left h1 {
    margin: 0 0 5px;

    font-size: 29px;
}


.header-left p {
    margin: 0;

    font-size: 13px;

    opacity: 0.9;
}


/* =========================================
   CONTAINER
   ========================================= */

.feedback-container {
    max-width: 1050px;

    margin: 35px auto;

    padding: 0 25px;

    box-sizing: border-box;
}


/* =========================================
   LAYOUT
   ========================================= */

.feedback-layout {
    display: grid;

    grid-template-columns:
        330px
        minmax(0, 1fr);

    gap: 25px;

    align-items: start;
}


/* =========================================
   LEFT INFORMATION
   ========================================= */

.feedback-info {
    padding: 30px;

    background: #4dd0e1;

    border-radius: 15px;

    box-sizing: border-box;
}


.info-icon {
    width: 58px;
    height: 58px;

    border-radius: 50%;

    background: white;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 25px;

    margin-bottom: 20px;
}


.feedback-info h2 {
    margin: 0 0 12px;

    font-size: 25px;

    color: #263238;
}


.feedback-info > p {
    margin: 0 0 25px;

    color: #37474f;

    font-size: 14px;

    line-height: 1.7;
}


.info-item {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-bottom: 17px;

    color: #37474f;

    font-size: 13px;
}


.info-item i {
    color: #00acc1;

    width: 20px;

    text-align: center;
}


/* =========================================
   FEEDBACK CARD
   ========================================= */

.feedback-card {
    background: white;

    border: 1px solid #e1eff1;

    border-radius: 15px;

    padding: 32px;

    box-shadow:
        0 5px 20px rgba(0,0,0,0.06);
}


/* =========================================
   CARD HEADING
   ========================================= */

.card-heading {
    display: flex;

    align-items: center;

    gap: 14px;

    padding-bottom: 22px;

    margin-bottom: 25px;

    border-bottom: 1px solid #edf3f4;
}


.heading-icon {
    width: 50px;
    height: 50px;

    border-radius: 10px;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 21px;
}


.card-heading h2 {
    margin: 0 0 5px;

    font-size: 21px;
}


.card-heading p {
    margin: 0;

    color: #78909c;

    font-size: 13px;
}


/* =========================================
   FORM
   ========================================= */

.form-group {
    margin-bottom: 24px;
}


.form-group label {
    display: block;

    margin-bottom: 8px;

    color: #37474f;

    font-size: 14px;

    font-weight: 600;
}


.required {
    color: #e53935;
}


.form-control {
    width: 100%;

    box-sizing: border-box;

    min-height: 44px;

    padding: 10px 13px;

    border: 1px solid #cfdfe2;

    border-radius: 7px;

    background: white;

    color: #263238;

    font-family: inherit;

    font-size: 14px;

    outline: none;

    transition: 0.2s ease;
}


.form-control:focus {
    border-color: #00acc1;

    box-shadow:
        0 0 0 3px rgba(0,172,193,0.10);
}


.comments-box {
    min-height: 140px;

    resize: vertical;

    line-height: 1.6;
}


.field-help {
    display: block;

    margin-top: 7px;

    color: #90a4ae;

    font-size: 11px;
}


/* =========================================
   STAR RATING
   ========================================= */

.rating-container {
    display: flex;

    align-items: center;

    gap: 7px;

    padding: 5px 0;
}


.star-btn {
    width: 38px;
    height: 38px;

    padding: 0;

    border: none;

    background: transparent;

    color: #cfd8dc;

    font-size: 25px;

    cursor: pointer;

    transition: 0.15s ease;
}


.star-btn:hover {
    color: #ffca28;

    transform: scale(1.12);
}


.star-btn.selected {
    color: #ffb300;
}


.rating-text {
    margin-top: 5px;

    color: #00acc1;

    font-size: 13px;

    font-weight: 600;
}


/* =========================================
   CHARACTER COUNT
   ========================================= */

.character-count {
    text-align: right;

    margin-top: 5px;

    color: #90a4ae;

    font-size: 11px;
}


/* =========================================
   FORM ACTIONS
   ========================================= */

.form-actions {
    display: flex;

    justify-content: flex-end;

    gap: 12px;

    padding-top: 18px;

    border-top: 1px solid #edf3f4;
}


.cancel-btn {
    padding: 11px 21px;

    border: 1px solid #cfdfe2;

    border-radius: 7px;

    background: white;

    color: #546e7a;

    font-weight: 600;

    cursor: pointer;
}


.cancel-btn:hover {
    background: #f5fafa;
}


.submit-btn {
    padding: 11px 22px;

    border: none;

    border-radius: 7px;

    background: #00acc1;

    color: white;

    font-weight: 600;

    cursor: pointer;
}


.submit-btn:hover {
    background: #008fa1;
}


.submit-btn:disabled {
    opacity: 0.65;

    cursor: not-allowed;
}


/* =========================================
   ERROR
   ========================================= */

.error-message {
    display: flex;

    align-items: center;

    gap: 10px;

    padding: 14px 16px;

    margin-bottom: 20px;

    border-radius: 8px;

    background: #ffebee;

    border: 1px solid #ffcdd2;

    color: #c62828;

    font-size: 13px;
}


/* =========================================
   SUCCESS
   ========================================= */

.success-card {
    background: white;

    border-radius: 15px;

    padding: 55px 35px;

    text-align: center;

    box-shadow:
        0 5px 20px rgba(0,0,0,0.06);

    border: 1px solid #e1eff1;
}


.success-icon {
    width: 75px;
    height: 75px;

    margin: 0 auto 20px;

    border-radius: 50%;

    background: #e8f5e9;

    color: #43a047;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 32px;
}


.success-card h2 {
    margin: 0 0 12px;

    color: #263238;

    font-size: 25px;
}


.success-card p {
    max-width: 550px;

    margin: 0 auto;

    color: #78909c;

    font-size: 14px;

    line-height: 1.7;
}


.success-actions {
    display: flex;

    justify-content: center;

    gap: 12px;

    margin-top: 25px;
}


.primary-btn {
    padding: 11px 20px;

    border: none;

    border-radius: 7px;

    background: #00acc1;

    color: white;

    font-weight: 600;

    cursor: pointer;
}


.secondary-btn {
    padding: 11px 20px;

    border: 1px solid #00acc1;

    border-radius: 7px;

    background: white;

    color: #00acc1;

    font-weight: 600;

    cursor: pointer;
}


/* =========================================
   NO FEEDBACK
   ========================================= */

.no-feedback-card {
    background: white;

    border-radius: 15px;

    padding: 55px 25px;

    text-align: center;

    border: 1px solid #e1eff1;

    box-shadow:
        0 5px 20px rgba(0,0,0,0.05);
}


.no-feedback-icon {
    width: 70px;
    height: 70px;

    margin: 0 auto 18px;

    border-radius: 50%;

    background: #e0f7fa;

    color: #00acc1;

    display: flex;

    align-items: center;

    justify-content: center;

    font-size: 29px;
}


.no-feedback-card h2 {
    margin: 0 0 10px;

    font-size: 23px;
}


.no-feedback-card p {
    max-width: 500px;

    margin: 0 auto 20px;

    color: #78909c;

    font-size: 14px;

    line-height: 1.6;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 800px) {

    .feedback-layout {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 600px) {

    .feedback-header {
        padding: 22px 20px;
    }

    .header-left h1 {
        font-size: 23px;
    }

    .feedback-container {
        margin-top: 20px;

        padding: 0 15px;
    }

    .feedback-card {
        padding: 23px;
    }

    .form-actions,
    .success-actions {
        flex-direction: column;
    }

    .cancel-btn,
    .submit-btn,
    .primary-btn,
    .secondary-btn {
        width: 100%;
    }

}

sp_widget.script:
(function() {

    /* =========================================
       DEFAULT DATA
       ========================================= */

    data.resolvedRequests = [];

    data.success = false;

    data.error = "";


    /* =========================================
       LOGIN CHECK
       ========================================= */

    if (!gs.isLoggedIn()) {

        data.error =
            "Please login before submitting feedback.";

        return;
    }


    /* =========================================
       ROLE CHECK
       ========================================= */

    if (!gs.hasRole("cfms_student") &&
        !gs.hasRole("admin")) {

        data.error =
            "You are not authorized to submit feedback.";

        return;
    }


    /* =========================================
       SUBMIT FEEDBACK
       ========================================= */

    if (input &&
        input.action == "submit_feedback") {


        var ticketId =
            input.ticket || "";

        var rating =
            parseInt(input.rating, 10);

        var comments =
            input.comments || "";


        /* -------------------------------------
           VALIDATION
           ------------------------------------- */

        if (!ticketId) {

            data.error =
                "Please select a resolved request.";

            return;
        }


        if (!rating ||
            rating < 1 ||
            rating > 5) {

            data.error =
                "Please select a rating from 1 to 5.";

            return;
        }


        if (!comments ||
            comments.trim() == "") {

            data.error =
                "Please enter your comments.";

            return;
        }


        /* -------------------------------------
           VERIFY INCIDENT

           The ticket MUST:
           1. Exist
           2. Belong to current student
           3. Be resolved/closed
           ------------------------------------- */

        var ticketGR =
            new GlideRecord("incident");


        if (!ticketGR.get(ticketId)) {

            data.error =
                "The selected request could not be found.";

            return;
        }


        /* Student ownership */

        if (ticketGR.getValue("caller_id") !=
            gs.getUserID()) {

            data.error =
                "You are not authorized to give feedback for this request.";

            return;
        }


        /* Resolved check */

        var ticketState =
            ticketGR.getValue("state");


        if (ticketState != "6" &&
            ticketState != "7") {

            data.error =
                "Feedback can only be submitted for a resolved request.";

            return;
        }


        /* -------------------------------------
           CHECK DUPLICATE FEEDBACK
           ------------------------------------- */

        var existingFeedback =
            new GlideRecord("u_cfms_feedback");


        existingFeedback.addQuery(
            "u_student",
            gs.getUserID()
        );

        existingFeedback.addQuery(
            "u_ticket",
            ticketId
        );

        existingFeedback.setLimit(1);

        existingFeedback.query();


        if (existingFeedback.next()) {

            data.error =
                "You have already submitted feedback for this request.";

            return;
        }


        /* -------------------------------------
           CREATE FEEDBACK
           ------------------------------------- */

        var feedbackGR =
            new GlideRecord("u_cfms_feedback");


        feedbackGR.initialize();


        feedbackGR.setValue(
            "u_student",
            gs.getUserID()
        );


        feedbackGR.setValue(
            "u_ticket",
            ticketId
        );


        feedbackGR.setValue(
            "u_rating",
            rating
        );


        feedbackGR.setValue(
            "u_comments",
            comments
        );


        var feedbackId =
            feedbackGR.insert();


        if (!feedbackId) {

            data.error =
                "Unable to submit feedback. Please try again.";

            return;
        }


        /* -------------------------------------
           SUCCESS
           ------------------------------------- */

        data.success = true;

        return;
    }


    /* =========================================
       GET RESOLVED REQUESTS
       ========================================= */

    var gr =
        new GlideRecord("incident");


    /*
     * Only this student's requests
     */

    gr.addQuery(
        "caller_id",
        gs.getUserID()
    );


    /*
     * Only resolved or closed
     */

    var stateQuery =
        gr.addQuery("state", "6");

    stateQuery.addOrCondition(
        "state",
        "7"
    );


    gr.orderByDesc(
        "sys_updated_on"
    );

    gr.query();


    while (gr.next()) {


        /*
         * Check whether feedback already exists
         */

        var feedbackCheck =
            new GlideRecord("u_cfms_feedback");


        feedbackCheck.addQuery(
            "u_student",
            gs.getUserID()
        );

        feedbackCheck.addQuery(
            "u_ticket",
            gr.getUniqueValue()
        );

        feedbackCheck.setLimit(1);

        feedbackCheck.query();


        /*
         * Only show requests that
         * have not already received feedback.
         */

        if (feedbackCheck.next()) {

            continue;

        }


        data.resolvedRequests.push({

            sys_id:
                gr.getUniqueValue(),

            number:
                gr.getValue("number"),

            short_description:
                gr.getValue(
                    "short_description"
                ),

            resolvedDate:
                gr.getDisplayValue(
                    "sys_updated_on"
                )

        });

    }

})();
